terraform {
  required_providers {
    azurerm = {
      source  = "hashicorp/azurerm"
      version = "~> 3.0"
    }
  }
  required_version = ">= 1.0.0"

  # Remote state in Azure Storage so the nightly drift-detection workflow can run
  # `terraform plan` against the real, shared state. Configured at init time via
  # `-backend-config` (see .github/workflows/drift-detection.yaml). For local-only
  # experimentation, run `terraform init -backend=false`.
  backend "azurerm" {}
}

provider "azurerm" {
  features {}
}

variable "resource_group_name" {
  type        = string
  description = "The name of the resource group for Sentinel infrastructure."
  default     = "rg-sentinel-secops-prod"
}

variable "location" {
  type        = string
  description = "The Azure region to deploy resources."
  default     = "eastus"
}

variable "workspace_name" {
  type        = string
  description = "The name of the Log Analytics workspace."
  default     = "law-sentinel-secops-prod"
}

variable "retention_in_days" {
  type        = number
  description = "The workspace data retention in days (Minimum 30 for Sentinel, 90 recommended for prod)."
  default     = 90
}

resource "azurerm_resource_group" "secops" {
  name     = var.resource_group_name
  location = var.location

  tags = {
    Environment = "Production"
    Workload    = "SecurityOperations"
    ManagedBy   = "Terraform"
  }
}

resource "azurerm_log_analytics_workspace" "sentinel" {
  name                = var.workspace_name
  location            = azurerm_resource_group.secops.location
  resource_group_name = azurerm_resource_group.secops.name
  sku                 = "PerGB2018"
  retention_in_days   = var.retention_in_days

  tags = {
    Environment = "Production"
    Workload    = "SecurityOperations"
    ManagedBy   = "Terraform"
  }
}

resource "azurerm_log_analytics_solution" "sentinel" {
  solution_name         = "SecurityInsights"
  location              = azurerm_resource_group.secops.location
  resource_group_name   = azurerm_resource_group.secops.name
  workspace_resource_id = azurerm_log_analytics_workspace.sentinel.id
  workspace_name        = azurerm_log_analytics_workspace.sentinel.name

  plan {
    publisher = "Microsoft"
    product   = "OMSGallery/SecurityInsights"
  }
}

output "resource_group_name" {
  description = "The name of the created Resource Group."
  value       = azurerm_resource_group.secops.name
}

output "log_analytics_workspace_id" {
  description = "The Workspace ID (Used for agent connections and API calls)."
  value       = azurerm_log_analytics_workspace.sentinel.workspace_id
}

output "log_analytics_workspace_name" {
  description = "The actual Azure resource name of the workspace."
  value       = azurerm_log_analytics_workspace.sentinel.name
}

# AWS side of the multi-cloud security architecture.
# Provisions an encrypted, private, versioned CloudTrail log bucket and the OIDC IAM role
# Microsoft Sentinel assumes to ingest AWS logs. Hardened to pass shift-left IaC scanning
# (KMS encryption, public-access block, log-file validation, scoped trust).
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

variable "aws_region" {
  type        = string
  description = "AWS region for the CloudTrail integration."
  default     = "us-east-1"
}

variable "sentinel_aws_account_id" {
  type        = string
  description = "AWS account ID Microsoft uses for the Sentinel AWS connector. Do NOT hard-code your own root account."
  default     = "197857026523" # Microsoft-published Sentinel S3 connector account
}

variable "sentinel_external_id" {
  type        = string
  description = "External ID (your Sentinel workspace ID) used to scope the AssumeRole trust."
  sensitive   = true
  default     = "00000000-0000-0000-0000-000000000000"
}

data "aws_caller_identity" "current" {}

# Customer-managed KMS key for CloudTrail + S3 at-rest encryption (with rotation).
resource "aws_kms_key" "cloudtrail" {
  description             = "CMK for Sentinel CloudTrail log encryption"
  enable_key_rotation     = true
  deletion_window_in_days = 7
  policy                  = data.aws_iam_policy_document.kms.json
}

resource "aws_kms_alias" "cloudtrail" {
  name          = "alias/sentinel-cloudtrail"
  target_key_id = aws_kms_key.cloudtrail.key_id
}

data "aws_iam_policy_document" "kms" {
  statement {
    sid       = "AllowRootAccountAdmin"
    effect    = "Allow"
    actions   = ["kms:*"]
    resources = ["*"]
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
  }
  statement {
    sid       = "AllowCloudTrailEncrypt"
    effect    = "Allow"
    actions   = ["kms:GenerateDataKey*", "kms:DescribeKey"]
    resources = ["*"]
    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
  }
}

# CloudTrail log bucket.
resource "aws_s3_bucket" "sentinel_cloudtrail" {
  bucket = "sentinel-multi-cloud-trail-logs-${data.aws_caller_identity.current.account_id}"
  #tfsec:ignore:aws-s3-enable-bucket-logging - object-level access is captured by the CloudTrail data events on this trail; a self-referential S3 server-access-log bucket is out of scope for this demo module.
}

resource "aws_s3_bucket_public_access_block" "sentinel_cloudtrail" {
  bucket                  = aws_s3_bucket.sentinel_cloudtrail.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_server_side_encryption_configuration" "sentinel_cloudtrail" {
  bucket = aws_s3_bucket.sentinel_cloudtrail.id

  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.cloudtrail.arn
    }
    bucket_key_enabled = true
  }
}

resource "aws_s3_bucket_versioning" "sentinel_cloudtrail" {
  bucket = aws_s3_bucket.sentinel_cloudtrail.id

  versioning_configuration {
    status = "Enabled"
  }
}

# CloudTrail requires write access to the bucket via a bucket policy.
data "aws_iam_policy_document" "cloudtrail_bucket" {
  statement {
    sid       = "AWSCloudTrailAclCheck"
    effect    = "Allow"
    actions   = ["s3:GetBucketAcl"]
    resources = [aws_s3_bucket.sentinel_cloudtrail.arn]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }
  }

  statement {
    sid       = "AWSCloudTrailWrite"
    effect    = "Allow"
    actions   = ["s3:PutObject"]
    resources = ["${aws_s3_bucket.sentinel_cloudtrail.arn}/AWSLogs/${data.aws_caller_identity.current.account_id}/*"]

    principals {
      type        = "Service"
      identifiers = ["cloudtrail.amazonaws.com"]
    }

    condition {
      test     = "StringEquals"
      variable = "s3:x-amz-acl"
      values   = ["bucket-owner-full-control"]
    }
  }
}

resource "aws_s3_bucket_policy" "sentinel_cloudtrail" {
  bucket = aws_s3_bucket.sentinel_cloudtrail.id
  policy = data.aws_iam_policy_document.cloudtrail_bucket.json
}

# CloudTrail configuration (multi-region, KMS-encrypted, log-file validation on).
resource "aws_cloudtrail" "sentinel_trail" {
  name                          = "sentinel-security-trail"
  s3_bucket_name                = aws_s3_bucket.sentinel_cloudtrail.id
  include_global_service_events = true
  is_multi_region_trail         = true
  enable_log_file_validation    = true
  kms_key_id                    = aws_kms_key.cloudtrail.arn

  depends_on = [aws_s3_bucket_policy.sentinel_cloudtrail]
}

# OIDC IAM role for Azure Sentinel cross-cloud trust (scoped via external ID).
resource "aws_iam_role" "sentinel_aws_connector" {
  name = "AzureSentinelAWSIntegrationRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::${var.sentinel_aws_account_id}:root"
        }
        Condition = {
          StringEquals = {
            "sts:ExternalId" = var.sentinel_external_id
          }
        }
      }
    ]
  })
}

# Attach least-privilege read access for Sentinel to pull CloudTrail logs from S3.
resource "aws_iam_role_policy_attachment" "sentinel_s3_read" {
  role       = aws_iam_role.sentinel_aws_connector.name
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess"
}

# This module deploys a SOAR auto-remediation playbook via Azure Logic Apps.
terraform {
  required_providers {
    azurerm = {
      source  = "hashicorp/azurerm"
      version = "~> 3.0"
    }
  }
}

provider "azurerm" {
  features {}
}

variable "location" {
  type        = string
  description = "Azure region for the SOAR resource group."
  default     = "eastus"
}

resource "azurerm_resource_group" "soar" {
  name     = "rg-sentinel-soar-prod"
  location = var.location
}

# The Logic App Workflow (the SOAR playbook).
resource "azurerm_logic_app_workflow" "isolate_host" {
  name                = "playbook-isolate-compromised-host"
  location            = azurerm_resource_group.soar.location
  resource_group_name = azurerm_resource_group.soar.name

  identity {
    type = "SystemAssigned"
  }
}

# Least privilege: Network Contributor scoped to the SOAR resource group ONLY, not the
# whole subscription. The playbook isolates a compromised host by modifying the NSGs
# delegated into this resource group, so it never needs subscription-wide write access.
resource "azurerm_role_assignment" "soar_network_contributor" {
  scope                = azurerm_resource_group.soar.id
  role_definition_name = "Network Contributor"
  principal_id         = azurerm_logic_app_workflow.isolate_host.identity[0].principal_id
}

# NOTE: Revoking Entra ID sessions is a Microsoft Graph (directory) permission, not an
# Azure RBAC role. In production, grant this managed identity the Graph app role
# (e.g. User.RevokeSessions.All) via the azuread provider. It is intentionally NOT a
# subscription-scoped "User Administrator" assignment, which would be wildly over-privileged.

# This Terraform module provisions a temporary Windows honeypot for attack simulation.
# SECURITY: the admin credential is generated at apply time with random_password and is
# never committed to source control. For a production deployment, persist it to Azure
# Key Vault and reference it through a data source rather than emitting it as an output.
terraform {
  required_providers {
    azurerm = { source = "hashicorp/azurerm", version = "~> 3.0" }
    random  = { source = "hashicorp/random", version = "~> 3.6" }
  }
}

provider "azurerm" {
  features {}
}

# Generated at apply time - replaces the previously hard-coded plaintext password.
resource "random_password" "honeypot_admin" {
  length           = 24
  special          = true
  override_special = "!@#%*()-_=+"
  min_lower        = 2
  min_upper        = 2
  min_numeric      = 2
  min_special      = 2
}

resource "azurerm_resource_group" "honeypot" {
  name     = "rg-sentinel-honeypot-temp"
  location = "eastus"
}

resource "azurerm_virtual_network" "vnet" {
  name                = "vnet-honeypot"
  address_space       = ["10.0.0.0/16"]
  location            = azurerm_resource_group.honeypot.location
  resource_group_name = azurerm_resource_group.honeypot.name
}

resource "azurerm_subnet" "subnet" {
  name                 = "internal"
  resource_group_name  = azurerm_resource_group.honeypot.name
  virtual_network_name = azurerm_virtual_network.vnet.name
  address_prefixes     = ["10.0.2.0/24"]
}

resource "azurerm_network_interface" "nic" {
  name                = "nic-honeypot"
  location            = azurerm_resource_group.honeypot.location
  resource_group_name = azurerm_resource_group.honeypot.name

  ip_configuration {
    name                          = "internal"
    subnet_id                     = azurerm_subnet.subnet.id
    private_ip_address_allocation = "Dynamic"
  }
}

resource "azurerm_windows_virtual_machine" "honeypot_vm" {
  name                  = "vm-honeypot-01"
  resource_group_name   = azurerm_resource_group.honeypot.name
  location              = azurerm_resource_group.honeypot.location
  size                  = "Standard_B2s"
  admin_username        = "socadmin"
  admin_password        = random_password.honeypot_admin.result # generated, never committed
  network_interface_ids = [azurerm_network_interface.nic.id]

  os_disk {
    caching              = "ReadWrite"
    storage_account_type = "Standard_LRS"
  }

  source_image_reference {
    publisher = "MicrosoftWindowsServer"
    offer     = "WindowsServer"
    sku       = "2022-Datacenter"
    version   = "latest"
  }
}

output "honeypot_admin_password" {
  description = "Generated honeypot admin password. Retrieve with: terraform output -raw honeypot_admin_password"
  value       = random_password.honeypot_admin.result
  sensitive   = true
}

package main

import (
	"flag"
	"fmt"
	"log"
	"os"
	"path/filepath"
	"strings"
)

func main() {
	// Define CLI Flags
	subscriptionID := flag.String("sub", "", "Azure Subscription ID")
	resourceGroup := flag.String("rg", "", "Azure Resource Group")
	workspaceName := flag.String("workspace", "", "Sentinel Workspace Name")
	rulesDir := flag.String("dir", "../sentinel-detection-pack/rules-yaml", "Directory containing YAML rules")
	apply := flag.Bool("apply", false, "Apply changes to Sentinel. Default is a safe dry-run (validate + map only).")
	flag.Parse()

	if *subscriptionID == "" || *resourceGroup == "" || *workspaceName == "" {
		log.Fatal("Error: -sub, -rg, and -workspace flags are required.")
	}

	mode := "DRY-RUN"
	if *apply {
		mode = "APPLY"
	}
	fmt.Printf("🚀 Initializing Sentinel Deployment Tool (Go-SecOps) [mode=%s]\n", mode)

	// Initialize Azure Deployer
	deployer, err := NewDeployer(*subscriptionID, *resourceGroup, *workspaceName, *apply)
	if err != nil {
		log.Fatalf("Failed to initialize Azure Deployer: %v", err)
	}

	// Traverse the directory and process YAML files
	var processed, failed int
	err = filepath.Walk(*rulesDir, func(path string, info os.FileInfo, err error) error {
		if err != nil {
			return err
		}
		if !info.IsDir() && (strings.HasSuffix(info.Name(), ".yaml") || strings.HasSuffix(info.Name(), ".yml")) {
			fmt.Printf("📦 Processing Rule: %s\n", info.Name())
			if err := deployer.DeployRule(path); err != nil {
				log.Printf("⚠️ Failed to deploy %s: %v", info.Name(), err)
				failed++
			} else {
				processed++
			}
		}
		return nil
	})

	if err != nil {
		log.Fatalf("Error walking rules directory: %v", err)
	}

	fmt.Printf("✅ Deployment execution completed. (%d processed, %d failed)\n", processed, failed)
	if failed > 0 {
		os.Exit(1)
	}
}

package main

import (
	"context"
	"fmt"
	"os"
	"strings"

	"github.com/Azure/azure-sdk-for-go/sdk/azidentity"
	"github.com/Azure/azure-sdk-for-go/sdk/resourcemanager/securityinsights/armsecurityinsights"
	"gopkg.in/yaml.v3"
)

// Deployer handles authentication and API interactions with Azure Sentinel.
type Deployer struct {
	client        *armsecurityinsights.AlertRulesClient
	resourceGroup string
	workspaceName string
	apply         bool // when false, validate + map only (dry-run); when true, push to Azure
}

// SentinelRule mirrors the YAML detection schema in sentinel-detection-pack/rules-yaml.
type SentinelRule struct {
	ID               string   `yaml:"id"`
	DisplayName      string   `yaml:"name"`
	Description      string   `yaml:"description"`
	Severity         string   `yaml:"severity"`
	Status           string   `yaml:"status"`
	Query            string   `yaml:"query"`
	QueryFrequency   string   `yaml:"queryFrequency"`
	QueryPeriod      string   `yaml:"queryPeriod"`
	TriggerOperator  string   `yaml:"triggerOperator"`
	TriggerThreshold int32    `yaml:"triggerThreshold"`
	Tactics          []string `yaml:"tactics"`
	Techniques       []string `yaml:"techniques"`
}

// NewDeployer authenticates using DefaultAzureCredential (supports OIDC, Managed Identity, CLI).
func NewDeployer(subscriptionID, resourceGroup, workspaceName string, apply bool) (*Deployer, error) {
	cred, err := azidentity.NewDefaultAzureCredential(nil)
	if err != nil {
		return nil, fmt.Errorf("authentication failed: %v", err)
	}

	clientFactory, err := armsecurityinsights.NewClientFactory(subscriptionID, cred, nil)
	if err != nil {
		return nil, err
	}

	return &Deployer{
		client:        clientFactory.NewAlertRulesClient(),
		resourceGroup: resourceGroup,
		workspaceName: workspaceName,
		apply:         apply,
	}, nil
}

// DeployRule parses a YAML detection file, maps it to a Sentinel Scheduled Alert Rule,
// and (when --apply is set) creates or updates it in the workspace via the ARM API.
func (d *Deployer) DeployRule(filePath string) error {
	data, err := os.ReadFile(filePath)
	if err != nil {
		return fmt.Errorf("could not read file: %v", err)
	}

	var rule SentinelRule
	if err := yaml.Unmarshal(data, &rule); err != nil {
		return fmt.Errorf("could not parse YAML: %v", err)
	}
	if rule.ID == "" || rule.Query == "" {
		return fmt.Errorf("rule missing required id/query fields")
	}

	scheduled := buildScheduledRule(rule)

	if !d.apply {
		fmt.Printf("   -> [dry-run] mapped %q (severity=%s, freq=%s, tactics=%s)\n",
			rule.DisplayName, rule.Severity, orDefault(rule.QueryFrequency, "PT5M"), strings.Join(rule.Tactics, ","))
		return nil
	}

	ctx := context.Background()
	if _, err := d.client.CreateOrUpdate(ctx, d.resourceGroup, d.workspaceName, rule.ID, scheduled, nil); err != nil {
		return fmt.Errorf("CreateOrUpdate failed: %w", err)
	}

	fmt.Printf("   -> deployed %q to %s\n", rule.DisplayName, d.workspaceName)
	return nil
}

// buildScheduledRule maps the YAML schema onto the ARM ScheduledAlertRule payload.
func buildScheduledRule(rule SentinelRule) *armsecurityinsights.ScheduledAlertRule {
	kind := armsecurityinsights.AlertRuleKindScheduled
	severity := mapSeverity(rule.Severity)
	triggerOp := armsecurityinsights.TriggerOperator(orDefault(rule.TriggerOperator, "GreaterThan"))

	tactics := make([]*armsecurityinsights.AttackTactic, 0, len(rule.Tactics))
	for _, t := range rule.Tactics {
		tactic := armsecurityinsights.AttackTactic(t)
		tactics = append(tactics, &tactic)
	}

	return &armsecurityinsights.ScheduledAlertRule{
		Kind: &kind,
		Properties: &armsecurityinsights.ScheduledAlertRuleProperties{
			DisplayName:         ptr(rule.DisplayName),
			Description:         ptr(rule.Description),
			Severity:            &severity,
			Enabled:             ptr(true),
			Query:               ptr(rule.Query),
			QueryFrequency:      ptr(orDefault(rule.QueryFrequency, "PT5M")),
			QueryPeriod:         ptr(orDefault(rule.QueryPeriod, "PT1H")),
			TriggerOperator:     &triggerOp,
			TriggerThreshold:    ptr(rule.TriggerThreshold),
			SuppressionDuration: ptr("PT1H"),
			SuppressionEnabled:  ptr(false),
			Tactics:             tactics,
		},
	}
}

func mapSeverity(s string) armsecurityinsights.AlertSeverity {
	switch strings.ToLower(strings.TrimSpace(s)) {
	case "high":
		return armsecurityinsights.AlertSeverityHigh
	case "medium":
		return armsecurityinsights.AlertSeverityMedium
	case "low":
		return armsecurityinsights.AlertSeverityLow
	default:
		return armsecurityinsights.AlertSeverityInformational
	}
}

// ptr returns a pointer to any value (the ARM models use pointer fields throughout).
func ptr[T any](v T) *T { return &v }

func orDefault(v, fallback string) string {
	if strings.TrimSpace(v) == "" {
		return fallback
	}
	return v
}
